const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const crypto = require('crypto');

const PROTO_PATH = './auth.proto';
const packageDefinition = protoLoader.loadSync(PROTO_PATH);
const authProto = grpc.loadPackageDefinition(packageDefinition).auth;

const TOKEN_STORE = new Map();
const SHUTDOWN_GRACE_PERIOD = 5000;
const SESSION_TTL_MS = 30 * 60 * 1000; // 30 minutes
let isShuttingDown = false;
let activeRequests = 0;

function generateHmac(data, secret) {
  return crypto.createHmac('sha256', secret).update(data).digest('hex');
}

function constantTimeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    return false;
  }
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    const dummy = Buffer.alloc(bufA.length);
    crypto.timingSafeEqual(bufA, dummy);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

function verifyTokenSignature(token, expectedSignature, secret) {
  const computed = generateHmac(token, secret);
  return constantTimeCompare(computed, expectedSignature);
}

function validateSession(call, callback) {
  activeRequests++;
  const { sessionId, token, signature } = call.request;

  if (isShuttingDown) {
    activeRequests--;
    return callback({
      code: grpc.status.UNAVAILABLE,
      message: 'Server is shutting down'
    });
  }

  const storedSession = TOKEN_STORE.get(sessionId);
  if (!storedSession) {
    activeRequests--;
    return callback(null, { valid: false, reason: 'session_not_found' });
  }

  // Enforce session expiration (CWE-613 mitigation).
  if (Date.now() - storedSession.createdAt > SESSION_TTL_MS) {
    TOKEN_STORE.delete(sessionId);
    activeRequests--;
    return callback(null, { valid: false, reason: 'session_expired' });
  }

  const secret = storedSession.secret;
  const isValidSignature = verifyTokenSignature(token, signature, secret);

  if (!isValidSignature) {
    activeRequests--;
    return callback(null, { valid: false, reason: 'invalid_signature' });
  }

  const isTokenMatch = verifyStoredToken(storedSession.token, token);

  if (!isTokenMatch) {
    activeRequests--;
    return callback(null, { valid: false, reason: 'token_mismatch' });
  }

  activeRequests--;
  return callback(null, { valid: true, reason: 'ok' });
}

function verifyStoredToken(stored, provided) {
  return constantTimeCompare(stored, provided);
}

function registerSession(call, callback) {
  activeRequests++;
  if (isShuttingDown) {
    activeRequests--;
    return callback({
      code: grpc.status.UNAVAILABLE,
      message: 'Server is shutting down'
    });
  }

  const sessionId = crypto.randomUUID();
  const token = crypto.randomBytes(32).toString('hex');
  const secret = crypto.randomBytes(32).toString('hex');
  const signature = generateHmac(token, secret);

  TOKEN_STORE.set(sessionId, { token, secret, createdAt: Date.now() });

  activeRequests--;
  return callback(null, { sessionId, token, signature, secret });
}

function startServer() {
  const server = new grpc.Server();
  server.addService(authProto.AuthService.service, {
    ValidateSession: validateSession,
    RegisterSession: registerSession
  });

  server.bindAsync('0.0.0.0:50051', grpc.ServerCredentials.createInsecure(), (err, port) => {
    if (err) {
      console.error('Failed to bind server:', err);
      process.exit(1);
    }
    console.log(`gRPC server running on port ${port}`);
    server.start();
  });

  function gracefulShutdown(signal) {
    console.log(`Received ${signal}. Starting graceful shutdown...`);
    isShuttingDown = true;

    const shutdownTimer = setTimeout(() => {
      console.log('Grace period expired, forcing shutdown');
      server.forceShutdown();
      process.exit(0);
    }, SHUTDOWN_GRACE_PERIOD);

    const checkInterval = setInterval(() => {
      if (activeRequests === 0) {
        clearInterval(checkInterval);
        clearTimeout(shutdownTimer);
        server.tryShutdown(() => {
          console.log('Server shut down gracefully');
          process.exit(0);
        });
      }
    }, 100);
  }

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  return server;
}

module.exports = { startServer, validateSession, registerSession, TOKEN_STORE };

if (require.main === module) {
  startServer();
}
